from __future__ import annotations

from datetime import datetime
from typing import Any, Literal
from uuid import UUID
from pydantic import BaseModel, ConfigDict

from db.schemas.general.primitives import TelegramPeerTypeSchema

SessionStateSchema = Literal["missing", "active", "error", "reset_required"]


class TelegramHarvesterCreate(BaseModel):
    """Insert shape for ``telegram_harvesters`` (``id`` generated by the DB)."""

    external_id: str
    label: str | None = None
    is_active: bool = True
    phone_number: str | None = None
    username: str | None = None
    first_name: str | None = None
    last_name: str | None = None
    session_state: SessionStateSchema = "missing"


class TelegramHarvesterSchema(BaseModel):
    """Row shape for ``telegram_harvesters`` (always includes DB ``id``)."""

    id: UUID
    external_id: str
    label: str | None = None
    is_active: bool = True
    phone_number: str | None = None
    username: str | None = None
    first_name: str | None = None
    last_name: str | None = None
    session_state: SessionStateSchema = "missing"
    created_at: datetime | None = None
    updated_at: datetime | None = None


class TelegramHarvesterPeerPermissionsSchema(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)

    harvester_id: UUID
    external_id: str
    peer_type: TelegramPeerTypeSchema

    notify_settings: dict[str, Any] | None = None
    read_inbox_max_id: int | None = None
    read_outbox_max_id: int | None = None
    unread_count: int | None = None
    pts: int | None = None

    can_view_participants: bool | None = None
    can_set_username: bool | None = None
    can_set_stickers: bool | None = None
    can_set_location: bool | None = None
    can_view_stats: bool | None = None
    can_delete_channel: bool | None = None
    blocked: bool | None = None
    has_scheduled: bool | None = None
    can_view_revenue: bool | None = None
    can_view_stars_revenue: bool | None = None

    admin_rights: dict[str, Any] | None = None
    updated_at: datetime


class TelegramHarvesterPeerRoleRow(BaseModel):
    id: UUID | None = None
    external_id: str
    harvester_id: UUID
    peer_type: TelegramPeerTypeSchema
    role: Literal["parent", "child"] = "child"
    assigned_at: datetime | None = None
    updated_at: datetime | None = None
